use Barryvdh\DomPDF\Facade\Pdf;
use Illuminate\Http\Client\ConnectionException;
use Illuminate\Support\Facades\Http;

/**
 * @param array{number: string, submittedAt: string, customerName: string, subject: string} $snapshot
 * @return array{status: string, message_id?: int, error_code?: int, retry_after?: int}
 */
function sendApplicationPdf(string $token, string $chatId, array $snapshot): array
{
    $pdf = Pdf::loadView('pdf.application-confirmation', $snapshot)
        ->setPaper('a4')
        ->output();

    if (!str_starts_with($pdf, '%PDF-') || strlen($pdf) > 8 * 1024 * 1024) {
        throw new RuntimeException('PDF не прошёл локальную проверку.');
    }

    $file = tmpfile();
    if ($file === false) {
        throw new RuntimeException('Временный файл недоступен.');
    }

    try {
        if (fwrite($file, $pdf) !== strlen($pdf) || !rewind($file)) {
            throw new RuntimeException('Не удалось подготовить файл к отправке.');
        }

        try {
            $response = Http::connectTimeout(5)->timeout(25)
                ->attach('document', $file, 'application.pdf', ['Content-Type' => 'application/pdf'])
                ->post('https://api.telegram.org/bot'.$token.'/sendDocument', [
                    'chat_id' => $chatId,
                    'caption' => 'Подтверждение заявки',
                ]);
        } catch (ConnectionException) {
            return ['status' => 'unknown'];
        }

        $messageId = $response->json('result.message_id');
        if ($response->successful() && $response->json('ok') === true && is_int($messageId)) {
            return ['status' => 'sent', 'message_id' => $messageId];
        }

        $errorCode = $response->json('error_code');
        if ($response->clientError() && $response->json('ok') === false && is_int($errorCode)) {
            $result = ['status' => 'rejected', 'error_code' => $errorCode];
            $delay = $response->json('parameters.retry_after');
            if ($errorCode === 429 && is_int($delay) && $delay > 0) {
                $result['retry_after'] = $delay;
            }
            return $result;
        }

        return ['status' => 'unknown'];
    } finally {
        if (is_resource($file)) {
            fclose($file);
        }
    }
}
